// GENERATED by scripts/build-io.mjs from src/ - edit the source, not this file.
// VTEX session data -> Weni contact fields.
//
// This mirrors what the official widget does (weni-ai/webchat-react,
// src/utils/vtexCustomFields.js): the same four field keys, the same resolution
// order, the same polling. Worth knowing WHY it looks like this:
//
// The `vtex_segment` cookie is HttpOnly on this store (measured, not assumed),
// so no injected script can read it - the official widget doesn't either. It
// reads the same data from `/api/segments`, and falls back to the FastStore
// session store or to the base64 token VTEX IO leaves on `window.__RUNTIME__`.
//
// The values travel as contact fields on the socket, and Flows writes them onto
// the contact (`PATCH /api/v2/internals/update_contacts_fields`, urn `ext:<from>`).

/** The field keys the platform already expects. Do not rename them. */
export type VtexFieldKey = 'vtex_account' | 'segment' | 'orderform' | 'session';

/** An orderForm id is 32 hex chars; anything else is a stale or partial read. */
const ORDER_FORM_ID = /^[a-f0-9]{32}$/;

const RESOLVE_INTERVAL_MS = 1000;
/** The official widget polls forever. We stop, so a non-VTEX page isn't hit all day. */
const RESOLVE_MAX_ATTEMPTS = 30;
/** The session token rotates while the chat is open, so this one keeps watching. */
const SESSION_INTERVAL_MS = 20_000;

declare global {
  interface Window {
    __RUNTIME__?: { account?: string; segmentToken?: string };
    VTEX_METADATA?: { account?: string };
    faststore_sdk_stores?: { get?: (key: string) => { read?: () => any } | undefined };
  }
}

function fastStore(key: string): any {
  try {
    return window.faststore_sdk_stores?.get?.(key)?.read?.() ?? null;
  } catch {
    return null;
  }
}

export function getVtexAccount(): string | null {
  return window.__RUNTIME__?.account || window.VTEX_METADATA?.account || null;
}

/** The whole segment payload as a string: channel, region, currency, utm_*, price tables. */
export async function getSegment(): Promise<string | null> {
  try {
    const response = await fetch('/api/segments');
    if (response.ok) {
      const segment = await response.json();
      if (segment) return JSON.stringify(segment);
    }
  } catch {
    /* not a VTEX origin, or offline - fall through */
  }

  const fromFastStore = fastStore('fs::session');
  if (fromFastStore) return JSON.stringify(fromFastStore);

  const token = window.__RUNTIME__?.segmentToken;
  if (token) {
    try {
      return atob(token);
    } catch {
      return null;
    }
  }
  return null;
}

export async function getOrderFormId(): Promise<string | null> {
  const fromFastStore = fastStore('fs::cart')?.id;
  if (fromFastStore) return String(fromFastStore);

  try {
    const response = await fetch('/api/checkout/pub/orderForm');
    if (!response.ok) return null;
    const data = await response.json();
    return data?.orderFormId ?? null;
  } catch {
    return null;
  }
}

export async function getValidOrderFormId(): Promise<string | null> {
  const id = await getOrderFormId();
  return typeof id === 'string' && ORDER_FORM_ID.test(id) ? id : null;
}

export async function getSessionToken(): Promise<string | null> {
  try {
    const response = await fetch('/api/sessions', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json' },
      body: '{}',
    });
    if (!response.ok) return null;
    const data = await response.json();
    return data?.sessionToken || null;
  } catch {
    return null;
  }
}

type SetField = (key: VtexFieldKey, value: string) => void;

/**
 * Resolves the four fields and reports each one as it becomes available.
 * Returns a stop function: call it when the panel closes or the conversation
 * is reset, or the timers outlive the chat they belong to.
 */
/**
 * `fallbackAccount` covers a page where the runtime globals aren't there (yet):
 * the store's account is known up front, so `vtex_account` never goes missing.
 */
export function startVtexFieldSync(setField: SetField, fallbackAccount?: string): () => void {
  let stopped = false;
  const timers: number[] = [];

  // Values that settle once: poll until there is one, then stop watching.
  const once: Array<{ key: VtexFieldKey; resolve: () => string | null | Promise<string | null> }> = [
    { key: 'vtex_account', resolve: () => getVtexAccount() || fallbackAccount || null },
    { key: 'segment', resolve: getSegment },
    { key: 'orderform', resolve: getValidOrderFormId },
  ];

  for (const { key, resolve } of once) {
    let attempts = 0;
    const poll = async () => {
      if (stopped) return;
      attempts += 1;
      let value: string | null = null;
      try {
        value = await resolve();
      } catch {
        /* keep polling: the storefront may still be booting */
      }
      if (stopped) return;
      if (value) {
        setField(key, value);
        return;
      }
      if (attempts < RESOLVE_MAX_ATTEMPTS) timers.push(window.setTimeout(poll, RESOLVE_INTERVAL_MS));
    };
    void poll();
  }

  // The session token can rotate (log in, store change), so it is re-sent
  // whenever it actually changes - never on every tick.
  let lastSession: string | null = null;
  const pollSession = async () => {
    if (stopped) return;
    let value: string | null = null;
    try {
      value = await getSessionToken();
    } catch {
      /* ignore and try again later */
    }
    if (stopped) return;
    if (value && value !== lastSession) {
      lastSession = value;
      setField('session', value);
    }
    timers.push(window.setTimeout(pollSession, SESSION_INTERVAL_MS));
  };
  void pollSession();

  return () => {
    stopped = true;
    timers.forEach((id) => window.clearTimeout(id));
    timers.length = 0;
  };
}
